import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';  
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  Future<List<CurrencyModel>>? _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _refreshData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData({bool refresh = false}) {
    if (refresh) {
      _currentPage = 0;
      _allCurrencies = [];
      _hasMore = true;
      _isLoadingMore = false;
    }

    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0)).then((CurrencyPage page) {
        final List<CurrencyModel> value = page.items;
        _allCurrencies = value;
        if (!refresh) {
          _filteredCurrenciesNotifier = ValueNotifier(value);
        } else {
          _filteredCurrenciesNotifier.value = value;
        }

        _hasMore = page.hasMore;
        _currentPage = 0;

        _fadeController.forward(from: 0.0); // перезапускаем анимацию

        currencyRepository.saveCurrencyList(value);

        return value;
      });
    });
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = _currentPage + 1;

    try {
      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage));

      if (!mounted) return;

      setState(() {
        _allCurrencies.addAll(page.items);
        _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        _hasMore = page.hasMore;
        _currentPage = nextPage;
      });

      currencyRepository.saveCurrencyList(page.items);
    } finally {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  void _refreshData() => _initData(refresh: true);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          final List<CurrencyModel> data = snapshot.data!;

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> listData, _) {
                      return Column(children: [
                        Expanded(
                          child: ListView.builder(
                            itemCount: listData.length + (_hasMore || _isLoadingMore ? 1 : 0),
                            itemBuilder: (BuildContext context, int index) {
                              if (index == listData.length) {
                                if (_isLoadingMore) {
                                  return const Center(child: Padding(padding: EdgeInsets.all(24), child: CircularProgressIndicator()));
                                } else if (_hasMore) {
                                  return Padding(
                                    padding: const EdgeInsets.symmetric(vertical: 16.0),
                                    child: ElevatedButton(
                                      onPressed: _loadNextPage,
                                      child: Text(context.loc.more ?? 'Show more'), // Need to check localization key
                                    ),
                                  );
                                }
                              }
                              final CurrencyModel currency = listData[index];
                              return Padding(
                                key: ValueKey(currency.id),
                                padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                                child: CurrencyCard(model: currency),
                              );
                            },
                            padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                          ),
                        ),
                      ]);
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
```

