7: class CurrencyListPage extends StatefulWidget {
8:   const CurrencyListPage({super.key});
9: 
10:   @override
11:   State<CurrencyListPage> createState() => _CurrencyListPageState();
12: }
13: 
14: class _CurrencyListPageState extends State<CurrencyListPage>
15:     with SingleTickerProviderStateMixin, WidgetsBindingObserver {
16:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
17: 
18:   late final AnimationController _fadeController;
19: 
20:   late Future<List<CurrencyModel>> _currencyListFuture;
21: 
22:   List<CurrencyModel> _allCurrencies = [];
23: 
24:   int _currentPage = 0;
25:   bool _hasMore = true;
26:   bool _isLoadingMore = false;
27: 
28:   @override
29:   void initState() {
30:     super.initState();
31:     WidgetsBinding.instance.addObserver(this);
32:     _initAnimation();
33:     _initData();
34:   }
35: 
36:   @override
37:   void dispose() {
38:     WidgetsBinding.instance.removeObserver(this);
39:     _filteredCurrenciesNotifier.dispose();
40:     _fadeController.dispose();
41:     super.dispose();
42:   }
43: 
44:   @override
45:   void didChangeAppLifecycleState(AppLifecycleState state) {
46:     if (state == AppLifecycleState.resumed) {
47:       _refreshData();
48:     }
49:   }
50: 
51:   void _initAnimation() {
52:     _fadeController = AnimationController(
53:       duration: const Duration(milliseconds: 400),
54:       vsync: this,
55:     );
56:   }
57: 
58:   void _initData() {
59:     final currencyRepository = context.read<CurrencyRepository>();
60: 
61:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0)).then((CurrencyPage page) {
62:       final List<CurrencyModel> value = page.items;
63:       _allCurrencies = value;
64:       _filteredCurrenciesNotifier = ValueNotifier(value);
65:       _hasMore = page.hasMore;
66: 
67:       _fadeController.forward(); // запускаем анимацию
68: 
69:       currencyRepository.saveCurrencyList(value);
70: 
71:       return value;
72:     });
73:   }
74: 
75:   void _refreshData() {
76:     setState(() {
77:       _currentPage = 0;
78:       _isLoadingMore = false;
79:       _hasMore = true;
80:     });
81:     _initData();
82:   }
83: 
84:   Future<void> _loadNextPage() async {
85:     if (_isLoadingMore || !_hasMore) return;
86: 
87:     setState(() {
88:       _isLoadingMore = true;
89:     });
90: 
91:     final currencyRepository = context.read<CurrencyRepository>();
92:     final nextPage = _currentPage + 1;
93: 
94:     try {
95:       final CurrencyPage page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: nextPage));
96:       if (!mounted) return;
97: 
98:       setState(() {
99:         _allCurrencies = List<CurrencyModel>.from(_allCurrencies)..addAll(page.items);
100:         _filteredCurrenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
101:         _currentPage = nextPage;
102:         _hasMore = page.hasMore;
103:         _isLoadingMore = false;
104:       });
105: 
106:       currencyRepository.saveCurrencyList(page.items);
107:     } catch (_) {
108:       if (!mounted) return;
109:       setState(() {
110:         _isLoadingMore = false;
111:       });
112:     }
113:   }
114: 
115:   void _filterCurrencies(String query) {
116:     final String lowerQuery = query.toLowerCase();
117:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
118:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
119:     });
120: 
121:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
122:   }
123: 
124:   @override
125:   Widget build(BuildContext context) {
126:     return Scaffold(
127:       appBar: AppBar(title: Text(context.loc.currencyRate)),
128:       body: FutureBuilder(
129:         future: _currencyListFuture,
130:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
131:           final List<CurrencyModel>? data = snapshot.data;
132:           if (data == null) return const SizedBox.shrink();
133: 
134:           return FadeTransition(
135:             opacity: _fadeController.view,
136:             child: Column(
137:               children: [
138:                 Padding(
139:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
140:                   child: SearchView(onChanged: _filterCurrencies),
141:                 ),
142:                 Expanded(
143:                   child: ValueListenableBuilder<List<CurrencyModel>>(
